// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListApplications Список заявок
	// (GET /applications)
	ListApplications(ctx context.Context, request ListApplicationsRequestObject) (ListApplicationsResponseObject, error)
	// CreateApplication Создать черновик
	// (POST /applications)
	CreateApplication(ctx context.Context, request CreateApplicationRequestObject) (CreateApplicationResponseObject, error)
	// GetApplication Карточка заявки
	// (GET /applications/{id})
	GetApplication(ctx context.Context, request GetApplicationRequestObject) (GetApplicationResponseObject, error)
	// UpdateApplication Изменить черновик
	// (PATCH /applications/{id})
	UpdateApplication(ctx context.Context, request UpdateApplicationRequestObject) (UpdateApplicationResponseObject, error)
	// AcceptOffer Принять условия
	// (POST /applications/{id}/accept)
	AcceptOffer(ctx context.Context, request AcceptOfferRequestObject) (AcceptOfferResponseObject, error)
	// CancelApplication Отменить заявку или отказаться от условий
	// (POST /applications/{id}/cancel)
	CancelApplication(ctx context.Context, request CancelApplicationRequestObject) (CancelApplicationResponseObject, error)
	// DecideApplication Решение андеррайтера
	// (POST /applications/{id}/decision)
	DecideApplication(ctx context.Context, request DecideApplicationRequestObject) (DecideApplicationResponseObject, error)
	// UploadDocument Загрузить документ
	// (POST /applications/{id}/documents)
	UploadDocument(ctx context.Context, request UploadDocumentRequestObject) (UploadDocumentResponseObject, error)
	// ListApplicationEvents Журнал аудита заявки
	// (GET /applications/{id}/history)
	ListApplicationEvents(ctx context.Context, request ListApplicationEventsRequestObject) (ListApplicationEventsResponseObject, error)
	// ProvideInfo Ответить на запрос уточнений
	// (POST /applications/{id}/provide-info)
	ProvideInfo(ctx context.Context, request ProvideInfoRequestObject) (ProvideInfoResponseObject, error)
	// RequestInfo Запросить документы или уточнения
	// (POST /applications/{id}/request-info)
	RequestInfo(ctx context.Context, request RequestInfoRequestObject) (RequestInfoResponseObject, error)
	// RetryChecks Повторить проверки
	// (POST /applications/{id}/retry-checks)
	RetryChecks(ctx context.Context, request RetryChecksRequestObject) (RetryChecksResponseObject, error)
	// SignApplication Подписать кодом
	// (POST /applications/{id}/sign)
	SignApplication(ctx context.Context, request SignApplicationRequestObject) (SignApplicationResponseObject, error)
	// RequestSigningCode Получить код подписания
	// (POST /applications/{id}/signing-code)
	RequestSigningCode(ctx context.Context, request RequestSigningCodeRequestObject) (RequestSigningCodeResponseObject, error)
	// SubmitApplication Подать заявку
	// (POST /applications/{id}/submit)
	SubmitApplication(ctx context.Context, request SubmitApplicationRequestObject) (SubmitApplicationResponseObject, error)
	// LookupCompany Автоподстановка по ИНН
	// (GET /companies/{inn})
	LookupCompany(ctx context.Context, request LookupCompanyRequestObject) (LookupCompanyResponseObject, error)
	// GetDocument Документ и результат распознавания
	// (GET /documents/{id})
	GetDocument(ctx context.Context, request GetDocumentRequestObject) (GetDocumentResponseObject, error)
	// ConfirmDocument Подтвердить значения документа
	// (POST /documents/{id}/confirm)
	ConfirmDocument(ctx context.Context, request ConfirmDocumentRequestObject) (ConfirmDocumentResponseObject, error)
	// DownloadDocument Файл документа
	// (GET /documents/{id}/file)
	DownloadDocument(ctx context.Context, request DownloadDocumentRequestObject) (DownloadDocumentResponseObject, error)
	// ListFeed Лента клиента
	// (GET /feed)
	ListFeed(ctx context.Context, request ListFeedRequestObject) (ListFeedResponseObject, error)
	// Health Проверка живости
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// Login Вход
	// (POST /login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Выход
	// (POST /logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Me Текущий пользователь и его компании
	// (GET /me)
	Me(ctx context.Context, request MeRequestObject) (MeResponseObject, error)
	// ListProducts Продукты
	// (GET /products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// RecommendProducts Подбор продукта по цели
	// (GET /products/recommendation)
	RecommendProducts(ctx context.Context, request RecommendProductsRequestObject) (RecommendProductsResponseObject, error)
	// GetSampleDocument Пример документа для демо
	// (GET /samples/{inn})
	GetSampleDocument(ctx context.Context, request GetSampleDocumentRequestObject) (GetSampleDocumentResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
}

// ListApplications operation middleware
func (sh *strictHandler) ListApplications(ctx echo.Context, params ListApplicationsParams) error {
	var request ListApplicationsRequestObject

	request.Params = params

	handler := func(ctx echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.ListApplications(ctx.Request().Context(), request.(ListApplicationsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListApplications")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(ListApplicationsResponseObject); ok {
		return validResponse.VisitListApplicationsResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

